import sys,math,collections,bisect
v=[]
def fib(n):
 a,b=0,1
 for _ in range(n):a,b=b,(a+b)%1000000007
 return a
def lis(v,non=False):
 d=[]
 for x in v:
  i=(bisect.bisect_right if non else bisect.bisect_left)(d,x)
  if i==len(d):d.append(x)
  else:d[i]=x
 return len(d)
def inc(v):
 d=[1]*len(v)
 for i in range(len(v)):
  d[i]+=sum(d[j] for j in range(i) if v[j]<v[i])
 return sum(d)
def nonadj(v):
 a=b=0
 for x in v:a,b=b,max(b,a+x)
 return b
def lps(v):
 n=len(v);d=[[0]*n for _ in v]
 for i in range(n-1,-1,-1):
  d[i][i]=1
  for j in range(i+1,n):d[i][j]=(2+(d[i+1][j-1] if j>i+1 else 0)) if v[i]==v[j] else max(d[i+1][j],d[i][j-1])
 return d[0][-1]
def run(v):
 best=cur=1
 for a,b in zip(v,v[1:]):cur=cur+1 if a==b else 1;best=max(best,cur)
 return best
def runalt(v):
 best=cur=1
 for a,b in zip(v,v[1:]):cur=cur+1 if a*b<0 else 1;best=max(best,cur)
 return best
def runsorted(v):
 best=cur=1
 for a,b in zip(v,v[1:]):cur=cur+1 if a<b else 1;best=max(best,cur)
 return best
